/**
 * Everything outside the script itself. The core verbs (events, timers, tasks and waiting, saved data,
 * the budget) are on `nf`; everything else is grouped into namespaces under it: `nf.server`,
 * `nf.commands`, `nf.players`, `nf.bots`, `nf.worlds`, `nf.structures`, `nf.centities`, `nf.spawning`,
 * `nf.menus`, `nf.dialogs`, `nf.items`, `nf.blocks`, `nf.recipes`, `nf.loot`, `nf.bossbars`,
 * `nf.teams`, `nf.schedule`, `nf.economy`, `nf.placeholders`, `nf.particles`, `nf.cutscenes`,
 * `nf.screens`, `nf.files`, `nf.text`, `nf.looks`, `nf.json`, `nf.http`, `nf.web`, `nf.wasm`,
 * `nf.network`, `nf.time`, `nf.random`, `nf.math` and `nf.test`. Plain functions on tables, so call
 * them with a dot: `nf.players.online()`.
 */
interface NfApi {
    /**
     * A saved table for the whole project, by name: `nf.data("shop")` is the same table in every script,
     * so a module keeps its own under its own name and two modules never collide. Each name is its own
     * file in the data directory, kept across restarts. It may hold strings, numbers, booleans, tables of
     * them (keyed by strings, or a list numbered from 1), and the API's own values: `Vec3`s, `Location`s,
     * `Item` tables, and `Player`, `Entity`, `Centity` and `World` handles, which come back as the same
     * types (a handle to something gone answers `nil` or `false`, as handles do). Anything else (a
     * function, a `Menu` window, a `Subscription`) is skipped when it's saved, with a line in the log
     * naming where it was (`data.inventory[3]: a function can't be saved`). The table is live: change it
     * and the change is saved, at the next autosave (every five minutes), when the project reloads and
     * when the server stops. It stays in memory across hot reloads rather than being read again, so a
     * script that reloads finds it as it left it. A table that would take more than 1 MiB isn't saved (the
     * last save stands), and the log says so. A name that isn't lowercase letters, digits and `_`
     * (starting with a letter or digit, at most 64 characters) is an error.
     */
    fun data(caller: Caller, name: String): Any?

    /**
     * A database. With no name it is this package's own: a SQLite file that belongs to it alone (each
     * package, a dependency included, has its own, under the server's `plugins/NetherForge/databases/`),
     * whose tables come from the package's `migrations/NNN_name.sql`, run in order when the project loads.
     * With a name it is one of the MySQL or PostgreSQL connections the server's owner set up under
     * `databases:` in the plugin's `config.yml`: the script names it and never sees a host, a user or a
     * password, and the connection opens only to the packages the owner lists for it. Either way it's the
     * same `Database`, so the same calls work (the SQL is the server's own dialect; see `Database` for
     * what differs). A name that isn't set up, or isn't open to this package, is an error.
     */
    fun db(caller: Caller, name: String?): LuaHandle.Database

    /**
     * One of this package's settings: what whoever runs the server set it to, or its default when they
     * haven't. Settings are declared in `netherforge.json`'s `settings` (each with a type, a default and a
     * description) and changed by the server's owner, never by scripts; a package reads only its own. The
     * value is a `boolean`, an `integer`, a `number` or a `string`, by the setting's type. A script that
     * reads a setting and doesn't listen for `setting_changed` is restarted when that setting changes; one
     * that listens hears the change instead. A name the package doesn't declare is an error.
     */
    fun config(caller: Caller, name: String): Any?
}

/**
 * The server itself: its clock, its performance, its version, its settings (players, message of the
 * day, whitelist), and saying or running things as the console.
 */
interface NfServerApi {
    /**
     * Server ticks since NetherForge started (20 a second): the clock to measure durations with. Use
     * `nf.server.unix_time()` only for timestamps that must mean something after a restart.
     */
    fun tick(caller: Caller): Long

    /**
     * The wall clock: milliseconds since 1970-01-01 UTC. For timestamps that outlive a restart (daily
     * rewards, cooldowns saved to a file); measure durations in ticks.
     */
    fun unixTime(caller: Caller): Long

    /** How many ticks the server managed in the last second or so: 20 when it keeps up, less when it lags. */
    fun ticksPerSecond(caller: Caller): Double

    /**
     * How long a tick has been taking lately, in milliseconds, averaged over the last few seconds. Over 50
     * means the server is lagging.
     */
    fun tickMilliseconds(caller: Caller): Double

    /** The running server's Minecraft version, like `"26.3"`. */
    fun minecraftVersion(caller: Caller): String

    /** Sends a line to everyone online and the console, as the server. */
    fun broadcast(caller: Caller, text: String)

    /** Runs a server command as the console, with the console's permissions. The leading slash is optional. */
    fun run(caller: Caller, command: String): Boolean

    /** How many players the server lets in at once: what the server list shows as its maximum. */
    fun maxPlayers(caller: Caller): Long

    /**
     * Changes how many players the server lets in at once, until it restarts (`server.properties` is left
     * alone). Nobody online is kicked when it drops below how many there are.
     */
    fun setMaxPlayers(caller: Caller, count: Long)

    /** The message of the day: the text under the server's name in the server list, as MiniMessage. */
    fun motd(caller: Caller): String

    /**
     * Changes the message of the day, until the server restarts (`server.properties` is left alone). To
     * change it for one ping only, listen to `server_list_ping`.
     */
    fun setMotd(caller: Caller, text: String)

    /** Whether the whitelist is on: only players on it (`player:is_whitelisted()`) and operators can join. */
    fun isWhitelistEnabled(caller: Caller): Boolean

    /** Turns the whitelist on or off. Turning it on doesn't kick anyone online who isn't on it. */
    fun setWhitelistEnabled(caller: Caller, enabled: Boolean)
}

/**
 * Slash commands a module adds to the server for as long as it runs, with typed arguments, tab
 * completion and usage messages from their declaration.
 */
interface NfCommandsApi {
    /**
     * Adds `/name` to the server for as long as the module runs. Only modules can register commands,
     * because a command outlives any one centity. The definition declares its arguments and subcommands;
     * NetherForge checks what's typed against them, answers mistakes with a usage message, completes them
     * as players type, and hands the handler typed values. Returns `false` when the name is already a
     * command, the server's or another module's. A handler that errors is logged and whoever typed the
     * command is told; the command stays. A name that isn't usable, or a definition with a mistake in it
     * (an unknown key, an unknown argument type, an optional argument before a required one), is an error.
     */
    fun register(caller: Caller, name: String, definition: CommandDefinitionOrFunction?, handler: LuaFunction?): Boolean
}

/** Players: everyone online, or anyone who has ever joined. */
interface NfPlayersApi {
    /** Everyone online. */
    fun online(caller: Caller): List<LuaHandle.Player>

    /**
     * A player by name (any case) or UUID: anyone who has ever joined this server, online or not, or `nil`
     * for someone who never has. For someone offline, `exists()` is `false` and what needs them in the
     * world (`position()`, `send_message`) answers `nil` or `false` until they come back.
     */
    fun get(caller: Caller, nameOrId: String): LuaHandle.Player?

    /**
     * Everyone who has ever joined this server, online or not, in no particular order. On a server that's
     * been running a long time that's a lot of players, so call it when you need it (building a
     * leaderboard) rather than every tick.
     */
    fun known(caller: Caller): List<LuaHandle.Player>

    /** Everyone who's banned, whose ban hasn't run out. */
    fun banned(caller: Caller): List<LuaHandle.Player>

    /** Everyone on the server's whitelist, whether it's on or not. */
    fun whitelisted(caller: Caller): List<LuaHandle.Player>
}

/**
 * Bots: fake players that scripts join to the server and drive, for opponents and teammates in games,
 * crowds, and anything a player does that an NPC can't. A bot is a real player to the server and to
 * every other plugin: it's on the player list and counted in the player count, its joins, moves,
 * clicks, chat and deaths are heard like anyone's, and it does everything by sending what a player's
 * client would (walking a step a tick, aiming before it clicks), so the game's rules and every other
 * plugin's checks apply to it. Each is a new player every time it joins (a fresh UUID, nothing of it
 * saved: no inventory, statistics or advancements kept), marked as an NPC for other plugins (the `NPC`
 * metadata they check to leave fake players alone), and it loads only the chunks right around it. A
 * bot belongs to the script that joined it and leaves when that script unloads. A package declares
 * `"requires": { "bots": true }` in its `netherforge.json`, and the server owner allows bots
 * (`bots.enabled` in `config.yml`, with `bots.max` online at once); until then a package that declares
 * them has a warning (`runtime.bots-disabled`). The editor's dev server always allows them. For a
 * figure that stands and looks like a player without being one, spawn a `Mannequin`: it costs far
 * less.
 */
interface NfBotsApi {
    /**
     * Joins a bot named `name` to the server, where it goes through everything a player's join does (the
     * server's checks, `player_join`, the resource pack, which it reports loaded without fetching). `nil,
     * err` when bots are off on this server, `bots.max` are online, someone of that name is online, or the
     * server turned it away. A name that isn't 3 to 16 letters, digits or `_` is an error. It takes ticks:
     * joining loads the world around it, so its bot arrives later: give `callback`, which is called with
     * `bot, err` once it's done, or call it inside a task (`nf.task`) without one, and it waits and
     * returns `bot, err`. Without a callback outside a task, it's an error. When it fails, `bot` is `nil`
     * and `err` says why.
     */
    fun join(caller: Caller, name: String, locationOrPosition: LocationOrVec3?, options: BotJoinOptions?): CompletionStage<LuaHandle.Bot>

    /** Every bot online, whoever joined it. */
    fun all(caller: Caller): List<LuaHandle.Bot>
}

/** The server's worlds: finding them, and making, loading and copying them. */
interface NfWorldsApi {
    /** Every loaded world, the default one first. */
    fun all(caller: Caller): List<LuaHandle.World>

    /** A world by name, or `nil` when the server has none by that name loaded. */
    fun get(caller: Caller, name: String): LuaHandle.World?

    /**
     * Makes a new world, and loads it: from then on it's the project's, so it can unload it
     * (`world:unload`), and it stays the project's across reloads and restarts. A name that isn't an id
     * (lowercase letters, digits and `_`), or that a world already has (loaded, or saved on the server),
     * is an error: `nf.worlds.load` loads a saved one. A `terrain` that isn't one of the project's
     * terrains is an error, and so are both a `generator` and a `terrain`, a `terrain` with another
     * environment than `"normal"`, and a `dimension_type` that isn't one of the project's dimension types
     * or that the server didn't start with. Making a world takes the server a moment.
     */
    fun create(caller: Caller, name: String, options: WorldCreateOptions?): LuaHandle.World?

    /**
     * Loads a world the server has saved but not loaded (one a script created and unloaded, or any other
     * world the server has), and returns it; one already loaded is just returned. `nil` when the server
     * has no world saved by that name. A name with characters a world's can't have is an error.
     */
    fun load(caller: Caller, name: String): LuaHandle.World?

    /**
     * Makes a new world from one of the project's maps (`maps/<map>/`): its files are copied, then the
     * server loads the copy as a world named `name`, the project's from then on (as for
     * `nf.worlds.create`). A map there's none of, or a `name` that isn't an id or that a world already has
     * (or that another copy is being made into), is an error at once. A copy that can't be made (the disk,
     * or the server refusing it) fails, and the server's log says so too. It works off the main thread, so
     * its world arrives later: give `callback`, which is called with `world, err` once it's done, or call
     * it inside a task (`nf.task`) without one, and it waits and returns `world, err`. Without a callback
     * outside a task, it's an error. When it fails, `world` is `nil` and `err` says why.
     */
    fun copy(caller: Caller, map: String, name: String): CompletionStage<LuaHandle.World>

    /** The server's main world: where things go when nothing says which. */
    fun default(caller: Caller): LuaHandle.World
}

/**
 * Structures: saved boxes of blocks that `world:place_structure` places. The project's are
 * `structures/<id>.nbt`; scripts save more with `world:save_structure`. A build (`builds/<id>/`) is a
 * structure too big for one file, kept in parts, which `world:place_gradually` places over several
 * ticks; these functions name both alike.
 */
interface NfStructuresApi {
    /**
     * Whether there's a structure or build by that id: one of the project's, or a structure a script
     * saved.
     */
    fun exists(caller: Caller, id: String): Boolean

    /**
     * How big a structure or build is, in blocks along x, y and z (before it's turned), or `nil` when
     * there's none by that id. One whose file (for a build, its last part's) can't be read is an error.
     */
    fun size(caller: Caller, id: String): Vec3?
}

/** Centity instances: spawning new ones and finding live ones. */
interface NfCentitiesApi {
    /**
     * A centity's `properties` from its `centity.json`, without one spawned: what `centity:properties()`
     * answers for every instance of it. An empty table when the file has none; a centity the project
     * doesn't have is an error. A new table each call.
     */
    fun properties(caller: Caller, kind: String): Any?

    /**
     * Puts a new instance of a centity into the world. Its entities exist, its script's body has run and
     * its `spawn` handlers have heard it by the time this returns. A centity the project doesn't have is
     * an error.
     */
    fun spawn(caller: Caller, kind: String, locationOrPosition: LocationOrVec3, options: CentitySpawnOptions?): LuaHandle.Centity?

    /**
     * The live centity instance with this id, or `nil` once it's gone. Ids come from `centity:id()` and
     * are fine to keep.
     */
    fun get(caller: Caller, id: String): LuaHandle.Centity?

    /**
     * Every live centity instance, or those the filter picks. Includes the caller's own instance. A filter
     * key that isn't one of `CentityFilter`'s is an error.
     */
    fun all(caller: Caller, filter: CentityFilter?): List<LuaHandle.Centity>
}

/**
 * Natural spawning (a centity's `spawning` block in `centity.json`): conditions a script decides,
 * which a `spawning` block names with `when`.
 */
interface NfSpawningApi {
    /**
     * Registers a condition a centity's `spawning.when` can name: the spawner asks `callback` about each
     * place where every other `spawning` rule of that centity fits, and the centity appears there only
     * when it answers `true`. Anything else (`false`, `nil`, an error) is no. It belongs to the script
     * that registered it and goes when that script unloads (a reload, the server stopping), so register it
     * in a module's body. A centity names it bare when it's in the same package as the registering script,
     * `ns:name` from another. A name another live script already registered is an error, and so is one
     * that isn't an id.
     */
    fun condition(caller: Caller, name: String, callback: LuaFunction)
}

/** The project's menus (`menus/<id>/`), and menus scripts make. */
interface NfMenusApi {
    /**
     * The window of a menu whose file says `"shared": true`: the one every player sees. A menu that isn't
     * shared has a window per player and no one to hand back, so this is `nil`; open one with
     * `player:open_menu`. A menu the project doesn't have is an error.
     */
    fun shared(caller: Caller, menu: String): LuaHandle.Menu?

    /**
     * Makes a menu from a table instead of a file: a `MenuTemplate`, which `player:open_menu(template)`
     * opens a new window of, as often as you like. The table says what `menu.json` would, in Lua spelling:
     * `type` (`"chest"`, the default, `"barrel"`, `"shulker_box"`, `"hopper"`, `"dispenser"`, `"dropper"`
     * or `"crafter"`), `rows` (a chest's 1 to 6, default 3), `title` (MiniMessage), `skin`
     * (`<pack>/<key>`), `locked` (default `true`) and `slots`, items by slot number from 0. A template has
     * no script of its own: put handlers on it (`template:on("click", ...)`), and they hear every window
     * made from it. It lasts as long as the script that created it. A key it doesn't take, a value of the
     * wrong type, a slot outside the window, an item the server doesn't have or a skin the project's
     * resource packs don't have is an error, checked by the same rules as `menu.json`.
     */
    fun create(caller: Caller, definition: LuaValue): LuaHandle.MenuTemplate
}

/** The project's dialogs (`dialogs/<id>/`), and dialogs scripts make. */
interface NfDialogsApi {
    /**
     * A dialog by id. There's one of each, so this always finds it; a dialog the project doesn't have is
     * an error.
     */
    fun get(caller: Caller, dialog: String): LuaHandle.Dialog

    /**
     * Makes a dialog from a table instead of a file. The table says what `dialog.json` would, in Lua
     * spelling (`after_action`, `can_close_with_escape`, an input's `max_length`, items as `Item` tables):
     * `title` (required), `type`, `body`, `inputs`, `buttons`, `columns`, `dialogs`, and the rest of the
     * file's fields except `script`. The `Dialog` it returns works like any other: `open_for`, `ask`,
     * `button(key)`, and `press` and `close` handlers on it and its buttons. Its id is made up and never
     * names a folder under `dialogs/`. It lasts as long as the script that created it; after that its
     * methods answer `nil` or `false` and its handlers are gone. A key it doesn't take, a value of the
     * wrong type, or anything `dialog.json` would have an error for (two buttons with one key, a
     * `dialog_list` naming a dialog there isn't) is an error.
     */
    fun create(caller: Caller, definition: LuaValue): LuaHandle.Dialog
}

/**
 * The project's items (`items/<id>/`): item kinds of its own, whose stacks the server can always tell
 * apart from any other stack of the same Minecraft kind.
 */
interface NfItemsApi {
    /**
     * A stack of a project item, as an `Item` table with every field its file sets, `item` naming it, and
     * `count` 1: hand it to `player:give_item`, `menu:set_item` or anything else that takes an item.
     * `overrides` sets fields of this stack: its `count`, its own `data`, or any other field. A field the
     * file sets too is the stack's only until the file changes: then the stack takes the file's look
     * again, keeping its count, damage and `data` (see the item format). A project item the project
     * doesn't have is an error.
     */
    fun create(caller: Caller, item: String, overrides: LuaValue?): ItemData

    /**
     * Which project item a stack is (its `item` field), or `nil` for a stack that isn't one. A stack
     * carries its project item wherever it goes, so this tells a ruby from any other paper.
     */
    fun id(caller: Caller, stack: ItemData): String?

    /**
     * A project item by id, to listen to what players do with it (`nf.items.get("ruby"):on("use", ...)`),
     * or `nil` when the project has no such item.
     */
    fun get(caller: Caller, item: String): LuaHandle.ProjectItem?

    /**
     * Every item the calling script can use: its own package's, and those the packages it depends on
     * export.
     */
    fun all(caller: Caller): List<LuaHandle.ProjectItem>
}

/**
